    """Restore background-covered cells of a row from a matching template row."""
    out = [row[:] for row in grid]
    if not grid:
        return out
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h = len(grid)
    for i, row in enumerate(grid):
        best = []
        for j, template in enumerate(grid):
            if i == j or len(template) != len(row):
                continue
            missing = [c for c, (a, b) in enumerate(zip(row, template))
                       if a == bg and b != bg]
            # The current row must match the template everywhere else.
            if missing and all(a == b or a == bg for a, b in zip(row, template)):
                best.append(missing)
        if best:
            # A matching complete row supplies the cells hidden by the dominant
            # background; indicate those reconstructed cells with color 1.
            missing = min(best, key=len)
            for c in missing:
                out[i][c] = 1
